<template><div><el-alert title="列表区块读取已发布内容；展示组件手动填写。按这里的顺序显示，保存外观草稿后预览，发布才生效。" :closable="false"/><div v-for="(b,i) in modelValue" :key="i" class="block"><div class="heading"><b>{{labels[b.kind]}}</b><el-switch v-model="b.enabled" active-text="显示"/><el-button link :disabled="i===0" @click="move(i,-1)">上移</el-button><el-button link :disabled="i===modelValue.length-1" @click="move(i,1)">下移</el-button><el-button link type="danger" @click="remove(i)">移除</el-button></div><el-form-item label="区块标题"><el-input v-model="b.title" maxlength="80" placeholder="留空用默认标题"/></el-form-item><template v-if="isList(b)"><el-form-item label="内容栏目"><SiteReferencePicker v-if="b.kind!=='PAGE'" v-model="b.channelId" type="channel" :kind="b.kind" clear-label="全部栏目"/><span v-else>全部单页</span></el-form-item><el-form-item label="显示条数"><el-input-number v-model="b.count" :min="1" :max="12" :precision="0"/></el-form-item><el-form-item label="推荐筛选"><el-switch v-model="b.featuredOnly" active-text="只看推荐"/></el-form-item></template><template v-else><el-form-item label="展示布局"><el-select v-model="b.layout"><el-option label="网格" value="grid"/><el-option label="列表" value="list"/></el-select></el-form-item><div v-for="(v,j) in b.items" :key="j" class="item"><el-form-item :label="b.kind==='FAQ'?'问题':'条目标题'"><el-input v-model="v.title" maxlength="80"/></el-form-item><el-form-item :label="b.kind==='FAQ'?'回答':'说明'"><el-input v-model="v.text" maxlength="500" type="textarea" :rows="2"/></el-form-item><el-form-item v-if="b.kind!=='FAQ'" label="图片"><AssetPicker v-model="v.assetId"/></el-form-item><el-form-item label="链接内容"><SiteReferencePicker v-model="v.contentId" clear-label="不跳转"/></el-form-item><el-button link :disabled="j===0" @click="swap(b.items,j,-1)">上移条目</el-button><el-button link :disabled="j===b.items.length-1" @click="swap(b.items,j,1)">下移条目</el-button><el-button link type="danger" @click="b.items.splice(j,1)">移除条目</el-button></div><el-button :disabled="b.items.length>=12" @click="b.items.push({title:'',text:'',assetId:0,contentId:0})">添加条目</el-button></template></div><div class="heading"><el-select v-model="selected" style="width:180px"><el-option v-for="(name,key) in labels" :key="key" :label="name" :value="key"/></el-select><el-button :disabled="modelValue.length>=15" @click="add">添加首页区块</el-button></div></div></template>
<script setup>
import {ref} from 'vue'
import AssetPicker from './AssetPicker.vue'
import SiteReferencePicker from './SiteReferencePicker.vue'
const props=defineProps({modelValue:{type:Array,default:()=>[]}}),emit=defineEmits(['update:modelValue']),selected=ref('SERVICE'),labels={ARTICLE:'文章列表',PRODUCT:'产品列表',PAGE:'单页列表',SERVICE:'服务介绍',ADVANTAGE:'我们的优势',CASE:'案例展示',PARTNER:'合作伙伴',FAQ:'常见问题'}
const isList=b=>['ARTICLE','PRODUCT','PAGE'].includes(b.kind)
function swap(rows,i,d){const j=i+d;if(j>=0&&j<rows.length)[rows[i],rows[j]]=[rows[j],rows[i]]}
function move(i,d){const rows=[...props.modelValue];swap(rows,i,d);emit('update:modelValue',rows)}
function remove(i){emit('update:modelValue',props.modelValue.filter((_,j)=>j!==i))}
function add(){const kind=selected.value;emit('update:modelValue',[...props.modelValue,{kind,title:'',enabled:true,channelId:0,count:6,featuredOnly:false,layout:'grid',items:[]}])}
</script><style scoped>.block{border:1px solid #ddd;border-radius:6px;padding:14px;margin:12px 0}.heading{display:flex;gap:12px;align-items:center;flex-wrap:wrap;margin-bottom:12px}.item{border-left:3px solid #ddd;padding:12px;margin:10px 0}.help{font-size:12px;color:#667;margin-left:8px}</style>